import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './empty-state.module.css'

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  icon?: ReactNode
  title: string
  description?: string
  action?: ReactNode
  size?: 'md' | 'lg'
}

export function EmptyState({
  icon,
  title,
  description,
  action,
  size = 'md',
  className,
  ...props
}: EmptyStateProps) {
  return (
    <div data-size={size} className={cn(styles['empty-state'], className)} {...props}>
      {icon && (
        <span className={styles['icon']} aria-hidden="true">
          {icon}
        </span>
      )}
      <h3 className={styles['title']}>{title}</h3>
      {description && <p className={styles['description']}>{description}</p>}
      {action && <div className={styles['action']}>{action}</div>}
    </div>
  )
}

@layer cascivo.component {
  .empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: var(--cascivo-space-2);
    padding: var(--cascivo-space-8);
    font-family: var(--cascivo-font-sans);
    color: var(--cascivo-color-text);

    &[data-size='lg'] {
      gap: var(--cascivo-space-3);
      padding: var(--cascivo-space-12);
    }
  }

  .icon {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    inline-size: 3rem;
    block-size: 3rem;
    margin-block-end: var(--cascivo-space-2);
    font-size: var(--cascivo-text-xl);
    line-height: 1;
    color: var(--cascivo-color-text-muted);
    background-color: var(--cascivo-color-bg-subtle);
    border-radius: var(--cascivo-radius-full);

    .empty-state[data-size='lg'] & {
      inline-size: 4rem;
      block-size: 4rem;
      font-size: var(--cascivo-text-2xl);
    }
  }

  .title {
    margin: 0;
    font-size: var(--cascivo-text-base);
    font-weight: var(--cascivo-font-semibold);
    line-height: var(--cascivo-leading-snug);

    .empty-state[data-size='lg'] & {
      font-size: var(--cascivo-text-lg);
    }
  }

  .description {
    margin: 0;
    max-inline-size: 40ch;
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-normal);

    .empty-state[data-size='lg'] & {
      font-size: var(--cascivo-text-base);
    }
  }

  .action {
    margin-block-start: var(--cascivo-space-2);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'EmptyState',
  description: 'Placeholder for views that have no data to display',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: ['md', 'lg'],
  props: [
    {
      name: 'icon',
      description: 'Icon element rendered in the component.',
      type: 'ReactNode',
      required: false,
    },
    { name: 'title', description: 'Title text for the component.', type: 'string', required: true },
    {
      name: 'description',
      description: 'Supporting description text.',
      type: 'string',
      required: false,
    },
    {
      name: 'action',
      description: 'Primary action shown in the component.',
      type: 'ReactNode',
      required: false,
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'md' | 'lg'",
      required: false,
      default: 'md',
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
    '--cascivo-color-text-muted',
    '--cascivo-color-bg-subtle',
    '--cascivo-radius-full',
  ],
  accessibility: {
    role: 'none',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    {
      title: 'Basic',
      code: '<EmptyState title="No results" description="Try adjusting your filters." />',
    },
    {
      title: 'With action',
      code: '<EmptyState icon="📄" title="No documents yet" description="Create your first document to get started." action={<Button>New document</Button>} />',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['empty', 'placeholder', 'zero-state', 'no-data'],
  intent: {
    whenToUse: [
      'Filling a view that has no data with guidance and a primary next step',
      'Explaining why a list/table is empty (no results, nothing created yet)',
      'Offering an action that resolves the empty condition (action prop)',
    ],
    whenNotToUse: [
      'Content is still loading — use Skeleton or Spinner',
      'An error occurred — use Alert to explain the failure',
    ],
    antiPatterns: [
      {
        bad: 'Showing an EmptyState while data is still fetching',
        good: 'A Skeleton during load, then EmptyState only if the result is empty',
        why: 'Conflating loading with empty tells the user there is no data when there may be',
      },
    ],
    related: [
      {
        name: 'Skeleton',
        relationship: 'alternative',
        reason: 'Skeleton covers the loading phase before data resolves',
      },
      {
        name: 'Alert',
        relationship: 'alternative',
        reason: 'Use Alert for error states rather than a generic empty state',
      },
    ],
    a11yRationale:
      'Presentational by role; the title carries the meaning as text and the action is a real focusable control, so keyboard and screen-reader users can act on the next step',
    content: {
      tone: 'Encouraging and concrete — name the next action',
      notes: 'Title states the situation; description tells the user what to do',
    },
    flexibility: [
      {
        area: 'size and action',
        level: 'flexible',
        note: 'Action and icon are optional; size scales for full-page vs in-panel use',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Text and background colors must resolve to --cascivo-* tokens',
      },
    ],
  },
}
